    <script text="text/javascript">
      resizeIframe();

      const closeButton = document.querySelector('#close-button');
      const rejectButton = document.querySelector('#reject-button');
      const acceptButton = document.querySelector('#accept-button');

      // Handle notification rejection by closing the modal
      closeButton.addEventListener('click', closeMessage);
      rejectButton.addEventListener('click', closeMessage);

      // Handle notification acceptance by triggering native notification popup
      acceptButton.addEventListener('click', function () {
        if (!appboyBridgeExists()) return;

        const pushOriginKey = 'push_notification_url_origin';
        const url = window.location.href;

        // Set origin Url and ask for native push permission
        appboyBridge.getUser().setCustomUserAttribute(pushOriginKey, url);
        appboyBridge.web.registerAppboyPushMessages();

        closeMessage();
      });

      function closeMessage() {
        if (!appboyBridgeExists()) return;

        appboyBridge.closeMessage();
      }

      function appboyBridgeExists() {
        const exists = typeof appboyBridge !== 'undefined';
        if (!exists) {
          console.warn('appboyBridge is not defined, it may be blocked by your browser.');
        }
        return exists;
      }

      function resizeIframe() {
        // the In-App message is displayed on web within an iframe (to avoid styling conflicts)
        const iframe = window.top.document.querySelector('iframe.ab-in-app-message');
        const head = window.top.document.head;

        // removes all classes except `ab-start-hidden` so that impressions are automatically logged
        iframe.setAttribute('class', 'ab-start-hidden');

        // removes the background and other default styles from the div tag on the parent page
        window.top.document.querySelector('.ab-iam-root').setAttribute('class', '');

        const containerStyle = document.createElement('style');
        containerStyle.innerHTML = `
        .push-wrapper {
          z-index: 99999;
          box-sizing: border-box;
          position: fixed;
          top: 58px;
          left: 0;
          right: 0;
          width: 100%;
          border: 0;
        }

        @media screen and (min-width: 435px) {
          .push-wrapper {
            top: 8px;
            width: 435px;
          }
        }
        `;

        head.appendChild(containerStyle);
        iframe.classList.add('push-wrapper');

        // makes the body scrollable again

        setTimeout(() => {
          window.top.document.body.classList.remove('ab-pause-scrolling');
        }, 100)
      }
    </script>
