      --bg-base:        #FFFFFF;
      --bg-low:         #F0F3F5;
      --overlay:        rgba(11, 11, 12, 0.6);

      --font-body: "wallie-fit", -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
      --font-heading:   "wallie-chunky", -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
    }

    /* ---- Design tokens (DARK MODE) ---- */
    @media (prefers-color-scheme: dark) {
      :root {
        --content-high:   #F0F3F5; /* Nearly white text */
        --content-mid:    #A3B8C1; /* Lighter grey-blue text */
        --content-low:    #5C7A89; /* Darker borders */
        --bg-base:        #1A2226; /* Deep dark background */
        --bg-low:         #29363D; /* Slightly lighter background for cards */
        --overlay:        rgba(0, 0, 0, 0.8); /* Darker overlay */
