    /* ---- Bottom sheet ---- */
    #modal {
      background: var(--bg-base);
      border-radius: 24px 24px 0 0;
      padding: 20px 24px 32px; 
      display: flex;
      flex-direction: column;
      gap: 20px; 
      width: 100%;
      max-width: 450px; 
