      -webkit-overflow-scrolling: touch;
      animation: slideUp 0.28s cubic-bezier(0.32, 0.72, 0, 1) both;
    }

    @keyframes slideUp {
      from { transform: translateY(100%); }
      to   { transform: translateY(0); }
    }

